function ProdsDiscountedPrice($string){
    $arr=explode(":",$string);
    $prices["kvmPRICE"]=str_replace("$","",$arr[0]);
    $arr=explode("|",$arr[1]);
    $prices["disPrice"]=$arr[0];
    $arr=explode("=",$arr[1]);
    $prices["disPercent"]=str_replace("%","",$arr[0]);
    $prices["discount"]=str_replace("$","",$arr[1]);

    return $prices;
}


function addedProdPrices($addedProdPricesString){
    $prodsStringArr=explode(" ",$addedProdPricesString);
    for($i=0;$i<count($prodsStringArr)-1;$i++){
        $a=explode(")",$prodsStringArr[$i]);
        $prodsArr[$a[0]]=ProdsDiscountedPrice($a[1]);
    }

    return $prodsArr;
}


